import urllib.parse

def parse_query(qs):
    result = {}
    if not qs:
        return result

    # Remove leading '?' if it exists
    if qs.startswith('?'):
        qs = qs[1:]

    pairs = qs.split('&')
    for pair in pairs:
        if not pair:
            continue

        parts = pair.split('=', 1)
        key = urllib.parse.unquote_plus(parts[0])
        value = urllib.parse.unquote_plus(parts[1]) if len(parts) > 1 else ""

        if key in result:
            if isinstance(result[key], list):
                result[key].append(value)
            else:
                result[key] = [result[key], value]
        else:
            result[key] = value

    return result
```

