def validate_ipv4(s: str) -> bool:
    parts = s.split('.')
    if len(parts) != 4:
        return False

    for part in parts:
        if not part.isdigit():
            return False

        # Check for leading zeros: 
        # '0' is allowed, but '01', '00', etc., are not.
        if len(part) > 1 and part[0] == '0':
            return False

        # Check range
        if not (0 <= int(part) <= 255):
            return False

    return True
