import re

def mask_secrets(text):
    def replace_match(match):
        key = match.group(1)
        if any(secret in key.lower() for secret in ['password', 'token', 'key']):
            return f"{key}=***"
        return match.group(0)

    # Matches key=value where key is alphanumeric/underscore 
    # and value is any non-whitespace, non-comma character sequence
    return re.sub(r'(\w+)=([^\s,]+)', replace_match, text)
