def strip_comments(code):
    result = []
    in_quote = None
    i = 0
    while i < len(code):
        char = code[i]
        if in_quote:
            result.append(char)
            if char == '\\':
                if i + 1 < len(code):
                    result.append(code[i+1])
                    i += 1
            elif char == in_quote:
                in_quote = None
            i += 1
        else:
            if char in ("'", '"'):
                in_quote = char
                result.append(char)
            elif char == '#':
                newline_pos = code.find('\n', i)
                if newline_pos == -1:
                    break
                else:
                    result.append('\n')
                    i = newline_pos
            else:
                result.append(char)
            i += 1
    return "".join(result)
```

