function debounceCount(fn, ms) {
  let timeoutId;
  let lastArgs;
  let lastContext;

  const call = function(...args) {
    lastArgs = args;
    lastContext = this;
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => {
      fn.apply(lastContext, lastArgs);
    }, ms);
  };

  const flush = () => {
    if (timeoutId) {
      clearTimeout(timeoutId);
      fn.apply(lastContext, lastArgs);
    }
  };

  return { call, flush };
}

module.exports = debounceCount;
```

