function deepClone(v, hash = new WeakMap()) {
  if (v === null || typeof v !== 'object') {
    return v;
  }

  if (v instanceof Date) {
    return new Date(v);
  }

  if (v instanceof RegExp) {
    return new RegExp(v);
  }

  if (hash.has(v)) {
    return hash.get(v);
  }

  const result = Array.isArray(v) ? [] : {};
  hash.set(v, result);

  for (const key in v) {
    if (Object.prototype.hasOwnProperty.call(v, key)) {
      result[key] = deepClone(v[key], hash);
    }
  }

  return result;
}

module.exports = deepClone;
```

