function rotateArray(arr, k) {
  const n = arr.length;
  if (n === 0) return [...arr];

  let shift = k % n;
  if (shift < 0) {
    shift += n;
  }

  const splitIndex = n - shift;
  const part1 = arr.slice(splitIndex);
  const part2 = arr.slice(0, splitIndex);

  return [...part1, ...part2];
}

module.exports = rotateArray;
