export type Handler = (e: { type: string }) => void;

export class Emitter {
  private handlers: Map<string, Handler[]> = new Map();

  on(t: string, h: Handler): void {
    const existing = this.handlers.get(t);
    if (existing) {
      existing.push(h);
    } else {
      this.handlers.set(t, [h]);
    }
  }

  emit(t: string): void {
    const handlers = this.handlers.get(t);
    if (handlers) {
      for (const handler of handlers) {
        handler({ type: t });
      }
    }
  }
}
