const isObject = (item) => {
  return item && typeof item === 'object' && !Array.isArray(item);
};

const mergeDeep = (a, b) => {
  if (!isObject(a) || !isObject(b)) {
    return b !== undefined ? b : a;
  }

  const result = { ...a };

  Object.keys(b).forEach((key) => {
    const bVal = b[key];
    const aVal = a[key];

    if (isObject(bVal) && isObject(aVal)) {
      result[key] = mergeDeep(aVal, bVal);
    } else if (isObject(bVal)) {
      result[key] = mergeDeep({}, bVal);
    } else {
      result[key] = bVal;
    }
  });

  return result;
};

module.exports = mergeDeep;
