export function maxBy<T>(arr: T[], f: (t: T) => number): T | undefined {
  if (arr.length === 0) {
    return undefined;
  }

  let maxElement: T = arr[0];
  let maxValue = f(arr[0]);

  for (let i = 1; i < arr.length; i++) {
    const currentElement = arr[i];
    const currentValue = f(currentElement);

    if (currentValue > maxValue) {
      maxValue = currentValue;
      maxElement = currentElement;
    }
  }

  return maxElement;
}
```

