import React, { useState, useRef } from 'react';
import { StyleSheet, Text, View, Button } from 'react-native';

const RefMutableValueExample = () => {
  const [stateCount, setStateCount] = useState(0);

  // useRef keeps the value across renders but does not trigger a re-render when changed
  const refCount = useRef(0);

  const handleStateChange = () => {
    setStateCount((prev) => prev + 1);
  };

  const handleRefChange = () => {
    refCount.current += 1;
    // This change is persistent but won't update the UI automatically
    console.log('Ref value updated to:', refCount.current);
  };

  return (
    <View style={styles.container}>
      <View style={styles.section}>
        <Text style={styles.title}>State Counter</Text>
        <Text style={styles.value}>{stateCount}</Text>
        <Button 
          title="Increment State (Triggers Re-render)" 
          onPress={handleStateChange} 
        />
      </View>

      <View style={styles.spacer} />

      <View style={styles.section}>
        <Text style={styles.title}>Ref Counter</Text>
        <Text style={styles.value}>{refCount.current}</Text>
        <Button 
          title="Increment Ref (No Re-render)" 
          onPress={handleRefChange} 
        />
        <Text style={styles.note}>
          Note: The Ref value will only update on screen 
          when the State changes.
        </Text>
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: '#f5f5f5',
    padding: 20,
  },
  section: {
    padding: 20,
    backgroundColor: '#fff',
    borderRadius: 10,
    width: '80%',
    elevation: 3,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.1,
    shadowRadius: 4,
    alignItems: 'center',
  },
  title: {
    fontSize: 18,
    fontWeight: 'bold',
    marginBottom: 10,
  },
  value: {
    fontSize: 40,
    marginBottom: 20,
  },
  spacer: {
    height: 40,
  },
  note: {
    marginTop: 15,
    fontSize: 12,
    color: '#666',
    textAlign: 'center',
  },
});

export default RefMutableValueExample;
```
